  ("formula", "def contractions(bars, avg_vol_50):\n    swings = zigzag(bars, pct=3.0)          # local highs and lows, 3% threshold\n    legs   = pairs(swings)                  # [(high, low), ...] most recent last\n    depths = [(h - l) / h for h, l in legs]\n\n    n_ok    = 2 &lt;= len(depths) &lt;= 4\n    tighten = all(depths[i+1] &lt; depths[i] * 0.75\n                  for i in range(len(depths) - 1))\n    vdu     = mean(vol_in_leg(legs[-1])) &lt; 0.70 * avg_vol_50\n\n    pivot = legs[-1][0]\n    return (n_ok and tighten and vdu), pivot"),
